Object.assign(window.STUDY_EXAMS,{"mln131_de01":{"subject":"mln131","legacyExamId":"de01_60","title":"Đề ôn tập 01 · 60 câu đã đối chiếu","short":"MLN131 · Đề 01","storageKey":"mln131_unified_de01_60_v1","legacyKey":"mln131_unified_de01_60_v0","mockEnabled":true,"notice":"Đề tổng hợp 60 câu đã đối chiếu giáo trình từ các nhóm ảnh, không lặp nguyên câu. Có ôn từng câu, thi thử và ôn lại câu sai. Hai câu có nhiều đáp án được ghi rõ cách chọn; mỗi câu giữ nhóm ảnh và số câu gốc.","questions":[{"id":1,"stem":"Trong quá trình xây dựng chủ nghĩa xã hội, liên minh giữa giai cấp công nhân, giai cấp nông dân và tầng lớp trí thức dưới góc độ nào giữ vai trò quyết định?","options":["Chính trị","Kinh tế","Văn hoá","Tư tưởng"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Ở giai đoạn xây dựng chủ nghĩa xã hội, tính tất yếu kinh tế của liên minh nổi lên như nhân tố quyết định nhất cho thắng lợi hoàn toàn của chủ nghĩa xã hội.","trick":"Gắn câu hỏi về vai trò quyết định của liên minh trong xây dựng CNXH với cơ sở kinh tế.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 175–176 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 6","image":"assets/mln131/q06.png","sourceExam":"mln131_01","sourceId":6,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 6","keywords":["liên minh","giữ vai trò quyết định"]},{"id":2,"stem":"Cách mạng vô sản là gì?","options":["Cuộc cách mạng của giai cấp nông dân và nhân dân lao động dưới sự lãnh đạo của Đảng Cộng sản, được thực hiện bằng con đường bạo lực cách mạng nhằm lật đổ chế độ tư bản chủ nghĩa, thiết lập nhà nước chuyên chính vô sản","Cuộc cách mạng của giai cấp công nhân và nhân dân lao động dưới sự lãnh đạo của Đảng Cộng sản, trên thực tế được thực hiện bằng con đường tuyên truyền giáo dục nhằm lật đổ chế độ tư bản chủ nghĩa, thiết lập nhà nước chuyên chính vô sản","Cuộc cách mạng của giai cấp công nhân và nhân dân lao động dưới sự lãnh đạo của Đảng Cộng sản, trên thực tế được thực hiện bằng con đường bạo lực cách mạng nhằm lật đổ chế độ phong kiến, thiết lập nhà nước chuyên chính vô sản","Cuộc cách mạng của giai cấp công nhân và nhân dân lao động dưới sự lãnh đạo của Đảng Cộng sản, được thực hiện bằng con đường bạo lực cách mạng nhằm lật đổ chế độ tư bản chủ nghĩa, thiết lập nhà nước chuyên chính vô sản"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Định nghĩa trong sách xác định lực lượng là giai cấp công nhân và nhân dân lao động, do Đảng Cộng sản lãnh đạo; trên thực tế dùng bạo lực cách mạng lật đổ chế độ tư bản chủ nghĩa và thiết lập nhà nước chuyên chính vô sản. Sách cũng lưu ý khả năng con đường hòa bình về lý thuyết.","trick":"Kiểm tra đủ: công nhân + nhân dân lao động; Đảng lãnh đạo; lật đổ tư bản; chuyên chính vô sản. A sai lực lượng, B sai con đường thực tế, C sai chế độ bị lật đổ.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 92–93 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 7","image":"assets/mln131/q07.png","sourceExam":"mln131_01","sourceId":7,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 7","keywords":["Cách mạng vô sản"]},{"id":3,"stem":"Đâu không phải là hạn chế của chủ nghĩa xã hội không tưởng Pháp?","options":["Không chỉ ra được những biện pháp để hiện thực hóa học thuyết của mình","Không phát hiện ra quy luật vận động, phát triển của xã hội loài người nói chung và xã hội tư bản chủ nghĩa nói riêng","Không phát hiện ra sứ mệnh lịch sử của giai cấp công nhân","Không biết được vai trò của nô lệ trong cách mạng xã hội"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn CNXH khoa học","detail":"Sách nêu ba hạn chế tương ứng A, B, C: chưa phát hiện quy luật phát triển, chưa tìm được lực lượng tiên phong là giai cấp công nhân và chưa chỉ ra biện pháp hiện thực cải tạo xã hội. D không thuộc các hạn chế được nêu.","trick":"Chú ý từ KHÔNG PHẢI. Bộ ba hạn chế: quy luật – lực lượng công nhân – biện pháp hiện thực.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 16–17 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 8","image":"assets/mln131/q08.png","sourceExam":"mln131_01","sourceId":8,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 8","keywords":["không phải","hạn chế","chủ nghĩa xã hội không tưởng Pháp"]},{"id":4,"stem":"Theo C. Mác và Ph. Ăngghen, hình thái kinh tế - xã hội cộng sản chủ nghĩa phát triển như thế nào?","options":["Phát triển theo hình xoáy ốc","Phát triển ý muốn chủ quan của con người","Phát triển theo sở thích của một đấng siêu nhiên nào đó trong vũ trụ","Phát triển từ thấp lên cao"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Sách trình bày hình thái kinh tế - xã hội cộng sản chủ nghĩa phát triển từ thấp lên cao qua hai giai đoạn: giai đoạn thấp và giai đoạn cao.","trick":"Câu hỏi về các giai đoạn của hình thái cộng sản chủ nghĩa → thấp lên cao.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 88 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 11","image":"assets/mln131/q11.png","sourceExam":"mln131_01","sourceId":11,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 11","keywords":["hình thái kinh tế - xã hội cộng sản chủ nghĩa","phát triển"]},{"id":5,"stem":"Theo quan điểm của chủ nghĩa Mác - Lênin, loài người đã trải qua các hình thức cộng đồng từ thấp đến cao theo thứ tự là gì?","options":["Thị tộc, bộ lạc, bộ tộc và dân tộc","Bộ tộc, bộ lạc, thị tộc và dân tộc","Dân tộc, thị tộc, bộ lạc và bộ tộc","Bộ lạc, bộ tộc, thị tộc và dân tộc"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Giáo trình liệt kê các hình thức cộng đồng từ thấp đến cao: thị tộc, bộ lạc, bộ tộc, dân tộc.","trick":"Nhớ đúng chuỗi: thị tộc → bộ lạc → bộ tộc → dân tộc.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 196 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 12","image":"assets/mln131/q12.png","sourceExam":"mln131_01","sourceId":12,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 12","keywords":["hình thức cộng đồng","từ thấp đến cao","theo thứ tự"]},{"id":6,"stem":"“Quyền lực nhà nước là thống nhất, có sự phân công, phối hợp, kiểm soát giữa các cơ quan nhà nước trong việc thực hiện các quyền lập pháp, hành pháp, tư pháp” được đề cập tại Đại hội lần thứ bao nhiêu của Đảng?","options":["X","XI","XII","XIII"],"correct":[2],"multiple":false,"gradable":true,"why":["Không phải đại hội mà trang 157 gắn với câu trích này.","Đây là đáp án của bình luận trong ảnh; không khớp đoạn và chú thích của giáo trình đã gửi.","Đúng theo giáo trình đang dùng: cả nội dung và chú thích đều ghi XII.","Đoạn sau của sách gắn XIII với cách diễn đạt “phân công rành mạch, phối hợp chặt chẽ và tăng cường kiểm soát”."],"topic":"Dân chủ và nhà nước XHCN","detail":"Theo đúng giáo trình đã gửi, trang 157 ghi Đại hội XII trước câu trích này, và chú thích 1 dẫn Văn kiện Đại hội XII, trang 171. Bình luận bên phải ảnh chọn B - XI và lập luận về lần đầu xác lập; đây là thông tin khác nguồn, chưa được giáo trình đang dùng xác nhận. Đề trên ảnh chỉ hỏi “được đề cập”, không có chữ “lần đầu”. Bản ôn giữ C theo giáo trình và hiển thị rõ khác biệt, không kết luận về đại hội đầu tiên trong lịch sử.","trick":"Theo sách trang 157: câu trích → XII; không đổi câu hỏi “được đề cập” thành “lần đầu”.","caution":"Khác nguồn: bình luận trong ảnh chọn B (XI), giáo trình trang 157 ghi XII. Chấm C theo phạm vi nguồn đã thống nhất; chưa dùng bình luận để kết luận về lần đầu xác lập.","reference":"Giáo trình CNXH khoa học (2021), trang 157 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 13","image":"assets/mln131/q13.png","studyNote":{"title":"Câu 56 nhóm ảnh 06 — khác biệt giữa bình luận và giáo trình","columns":["Nguồn đối chiếu","Nội dung"],"rows":[["Bình luận bên phải ảnh","Chọn B — Đại hội XI; lập luận về đại hội đầu tiên xác lập đầy đủ nguyên tắc."],["Giáo trình trang 157","Nội dung và chú thích 1 đều ghi Đại hội XII; bản ôn chấm C theo sách."]],"caption":"Đề trên ảnh chỉ hỏi “được đề cập”, không hỏi “lần đầu”. Bảng ghi nhận khác nguồn, chưa xác minh độc lập luận điểm lịch sử trong bình luận. Giữ nguyên đáp án C của câu 13 nhóm ảnh 01."},"sourceExam":"mln131_01","sourceId":13,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 13","keywords":["phân công, phối hợp, kiểm soát","Đại hội lần thứ bao nhiêu"]},{"id":7,"stem":"Trong thời kì quá độ lên chủ nghĩa xã hội, bên cạnh sự liên minh chặt chẽ trên cơ sở thống nhất lợi ích kinh tế giữa giai cấp công nhân, nông dân và trí thức, còn xuất hiện vấn đề gì?","options":["Xuất hiện những mâu thuẫn lợi ích ở những mức độ khác nhau","Xuất hiện sự đấu tranh kịch liệt trong hệ thống chuyên chính vô sản","Xuất hiện sự chống phá của các giai cấp trong liên minh","Xuất hiện sự chuyên quyền, độc đoán của một bộ phận"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Quan hệ lợi ích trong liên minh vừa có thống nhất về kinh tế vừa xuất hiện mâu thuẫn lợi ích ở các mức độ khác nhau. Vì vậy cần phát hiện và giải quyết mâu thuẫn phù hợp.","trick":"Thống nhất lợi ích không đồng nghĩa hết mâu thuẫn lợi ích.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 176 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 21","image":"assets/mln131/q21.png","sourceExam":"mln131_01","sourceId":21,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 21","keywords":["thống nhất lợi ích kinh tế","còn xuất hiện"]},{"id":8,"stem":"Nhà nước xã hội chủ nghĩa là nhà nước của ai?","options":["Nhân dân lao động","Công nhân - Nông dân","Công nhân - Nông dân - Trí thức","Lãnh đạo, Đảng viên"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Dân chủ và nhà nước XHCN","detail":"Sách xác định nhà nước xã hội chủ nghĩa đưa nhân dân lao động lên địa vị làm chủ; nhà nước do nhân dân lao động làm chủ là nhà nước của dân, do dân, vì dân.","trick":"“Của ai?” → nhân dân lao động. Phân biệt với câu hỏi về bản chất giai cấp công nhân của nhà nước.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 143; 157 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 23","image":"assets/mln131/q23.png","sourceExam":"mln131_01","sourceId":23,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 23","keywords":["Nhà nước xã hội chủ nghĩa","của ai"]},{"id":9,"stem":"Dựa trên phương diện kinh tế - xã hội, giai cấp công nhân được hiểu như thế nào?","options":["Sản phẩm của nền sản xuất đại công nghiệp","Chủ thể của nền sản xuất đại công nghiệp","Là người mua sức lao động và đi bóc lột giá trị thặng dư","Chủ thể và sản phẩm của nền sản xuất đại công nghiệp"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Ở phương diện kinh tế - xã hội, giai cấp công nhân vừa là sản phẩm vừa là chủ thể của nền sản xuất đại công nghiệp. A và B chỉ nêu một vế; C mô tả phía mua sức lao động.","trick":"Cặp đầy đủ: sản phẩm VÀ chủ thể của đại công nghiệp.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 53 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 26","image":"assets/mln131/q26.png","sourceExam":"mln131_01","sourceId":26,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 26","keywords":["phương diện kinh tế - xã hội","giai cấp công nhân"]},{"id":10,"stem":"Đại hội XIII của Đảng Cộng sản Việt Nam đã đề ra mục tiêu gì vào năm 2045 trên con đường xây dựng chủ nghĩa xã hội?","options":["Trở thành nước phát triển, có kinh tế tri thức, thu nhập trung bình cao","Trở thành con rồng Châu Á","Trở thành nước phát triển, thu nhập cao","Trở thành nước đang phát triển, có thu nhập trung bình cao"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Mục tiêu năm 2045 trong sách là trở thành nước phát triển, thu nhập cao. Mục tiêu năm 2030 là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao.","trick":"2045 → phát triển + thu nhập cao; 2030 → đang phát triển + thu nhập trung bình cao.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 118 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 27","image":"assets/mln131/q27.png","sourceExam":"mln131_01","sourceId":27,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 27","keywords":["Đại hội XIII","mục tiêu","2045"]},{"id":11,"stem":"Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay, hình thức phân phối nào giữ vai trò chủ đạo?","options":["Phân phối theo lao động","Phân phối quỹ phúc lợi xã hội","Phân phối theo nhu cầu","Phân phối theo bao cấp"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Thời kỳ quá độ có nhiều hình thức phân phối; phân phối theo lao động giữ vai trò chủ đạo, bên cạnh phân phối theo mức đóng góp và quỹ phúc lợi xã hội.","trick":"Chủ đạo trong thời kỳ quá độ → theo lao động.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 112 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 31","image":"assets/mln131/q31.png","sourceExam":"mln131_01","sourceId":31,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 31","keywords":["hình thức phân phối","chủ đạo"]},{"id":12,"stem":"Theo quan điểm của chủ nghĩa Mác - Lênin, vì sao thời kỳ quá độ lên chủ nghĩa xã hội là tất yếu?","options":["Vì giai cấp vô sản cần có thời gian để cải tạo xã hội cũ và xây dựng xã hội mới xã hội chủ nghĩa","Vì chủ nghĩa xã hội là thực hiện ý chí chủ quan của giai cấp công nhân và nhân dân lao động","Vì chủ nghĩa xã hội thực hiện sự thống trị của giai cấp, tầng lớp nghèo nàn trong xã hội","Vì chủ nghĩa xã hội là giai đoạn chuyển tiếp của hình thái kinh tế - xã hội cộng sản chủ nghĩa"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Không thể có ngay xã hội mới chỉ bằng mong muốn. Giai cấp vô sản cần thời gian cải tạo xã hội cũ và xây dựng xã hội xã hội chủ nghĩa.","trick":"Hỏi vì sao cần thời kỳ quá độ → cần thời gian cải tạo cũ, xây dựng mới.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 104–105 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 33","image":"assets/mln131/q33.png","sourceExam":"mln131_01","sourceId":33,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 33","keywords":["vì sao","thời kỳ quá độ","tất yếu"]},{"id":13,"stem":"Cơ cấu xã hội ở Việt Nam muốn biến đổi theo hướng tích cực phải dựa trên cơ sở gì?","options":["Tăng trưởng kinh tế bằng mọi giá","Sự giàu mạnh của các tổ chức, tập đoàn kinh tế lớn, cạnh tranh được với nước ngoài","Sự phát triển của thành phần kinh tế nhà nước và tập thể","Tăng trưởng, phát triển kinh tế nhanh và bền vững"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Giáo trình nêu cơ sở của biến đổi tích cực cơ cấu xã hội là tăng trưởng và phát triển kinh tế nhanh, bền vững; gắn với văn hóa, tiến bộ, công bằng xã hội và bảo vệ môi trường.","trick":"Cơ cấu xã hội tích cực → nền kinh tế nhanh VÀ bền vững; tránh “bằng mọi giá”.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 188 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 37","image":"assets/mln131/q37.png","sourceExam":"mln131_01","sourceId":37,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 37","keywords":["Cơ cấu xã hội","biến đổi theo hướng tích cực","cơ sở"]},{"id":14,"stem":"C. Mác và Ph. Ăngghen từng cho rằng: “Quan hệ thứ ba tham dự ngay từ đầu vào quá trình phát triển lịch sử: hằng ngày tái tạo ra đời sống của bản thân mình, con người bắt đầu tạo ra những người khác, sinh sôi nảy nở”. Cụm từ “quan hệ thứ ba” trong câu trên dùng để chỉ cái gì?","options":["Phát triển","Sinh nở","Bạn bè","Gia đình"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Gia đình","detail":"Ngay sau nội dung trích, sách xác định đó là quan hệ giữa chồng và vợ, cha mẹ và con cái, tức gia đình. “Sinh nở” chỉ là một chi tiết trong đoạn, không phải toàn bộ quan hệ được hỏi.","trick":"Quan hệ vợ chồng + cha mẹ con cái → gia đình.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 240 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 39","image":"assets/mln131/q39.png","sourceExam":"mln131_01","sourceId":39,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 39","keywords":["Quan hệ thứ ba","sinh sôi nảy nở"]},{"id":15,"stem":"Công cuộc đổi mới do Đảng Cộng sản Việt Nam khởi xướng và lãnh đạo tại Đại hội lần thứ bao nhiêu?","options":["Lần thứ IV","Lần thứ VI","Lần thứ X","Lần thứ XIII"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Sách xác định công cuộc đổi mới được khởi xướng và lãnh đạo từ Đại hội VI năm 1986.","trick":"Đổi mới → VI → 1986.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 35; 150 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 40","image":"assets/mln131/q40.png","sourceExam":"mln131_01","sourceId":40,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 40","keywords":["Công cuộc đổi mới","Đại hội lần thứ bao nhiêu"]},{"id":16,"stem":"Tại sao tôn giáo là một phạm trù lịch sử?","options":["Là sản phẩm của đấng thần linh","Là do điều kiện kinh tế - xã hội sinh ra","Tôn giáo tồn tại và phát triển song song với quá trình hình thành, phát triển và tiêu vong của con người","Tôn giáo ra đời, tồn tại và biến đổi trong một giai đoạn lịch sử nhất định của loài người"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Tính lịch sử của tôn giáo thể hiện ở sự hình thành, tồn tại, phát triển và biến đổi trong những giai đoạn lịch sử nhất định. Điều kiện kinh tế - xã hội và lịch sử thay đổi thì tôn giáo cũng thay đổi. B mới đề cập nguồn gốc, chưa diễn đạt đầy đủ tính lịch sử.","trick":"Phạm trù lịch sử → có hình thành, biến đổi theo điều kiện lịch sử.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 218 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 44","image":"assets/mln131/q44.png","sourceExam":"mln131_01","sourceId":44,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 44","keywords":["tôn giáo","phạm trù lịch sử"]},{"id":17,"stem":"Theo nghĩa rộng, khái niệm dân tộc được hiểu như thế nào?","options":["Một quốc gia, toàn bộ nhân dân của một nước","Một dân tộc cụ thể cùng chung sống trong một lãnh thổ quốc gia nhất định","Tất cả các quốc gia đang sinh sống trên trái đất","Một dân tộc có chung văn hóa, có thể sống trên nhiều quốc gia khác nhau"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Theo nghĩa rộng, dân tộc là cộng đồng tạo thành nhân dân một nước; khái niệm dùng để chỉ một quốc gia, toàn bộ nhân dân của quốc gia đó.","trick":"Nghĩa rộng → quốc gia, toàn bộ nhân dân; không chỉ một tộc người.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 196–197 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 47","image":"assets/mln131/q47.png","sourceExam":"mln131_01","sourceId":47,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 47","keywords":["nghĩa rộng","dân tộc"]},{"id":18,"stem":"Hình thức dân chủ nào ở Việt Nam mà thông qua nó, người dân bằng hành động của mình thực hiện quyền làm chủ nhà nước và xã hội, không thông qua chủ thể trung gian?","options":["Hình thức dân chủ trực tiếp","Hình thức dân chủ gián tiếp","Hình thức dân chủ đại nghị","Hình thức dân chủ công khai"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Dân chủ và nhà nước XHCN","detail":"Dân chủ trực tiếp là hình thức nhân dân bằng hành động trực tiếp của mình thực hiện quyền làm chủ nhà nước và xã hội; dân chủ gián tiếp thông qua đại diện được ủy quyền.","trick":"Tự thực hiện, không qua trung gian → trực tiếp.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 153 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 48","image":"assets/mln131/q48.png","sourceExam":"mln131_01","sourceId":48,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 48","keywords":["bằng hành động của mình","không thông qua chủ thể trung gian"]},{"id":19,"stem":"Một bộ phận giai cấp công nhân đã tham gia vào sở hữu một lượng tư liệu sản xuất của xã hội thông qua chế độ cổ phần là một biểu hiện của xu hướng nào của giai cấp công nhân trong thời đại hiện nay?","options":["Xu hướng “trí tuệ hóa”","Xu hướng “trung lưu hóa”","Xu hướng thỏa hiệp","Xu hướng cải cách"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Sách trình bày việc một bộ phận công nhân tham gia sở hữu tư liệu sản xuất qua cổ phần hóa trong xu hướng trung lưu hóa. Sách lưu ý sở hữu ít cổ phần không có nghĩa họ nắm quyền quyết định sản xuất và phân phối lợi nhuận.","trick":"Cổ phần, sở hữu một lượng tư liệu sản xuất → trung lưu hóa; tri thức, kỹ năng → trí tuệ hóa.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 67–68 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 56","image":"assets/mln131/q56.png","sourceExam":"mln131_01","sourceId":56,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 56","keywords":["sở hữu","chế độ cổ phần","xu hướng"]},{"id":20,"stem":"“Đạo Cao Đài, Phật giáo Hòa Hảo là hai trong số những tôn giáo nội sinh ở Việt Nam. Lịch sử từng ghi nhận rằng hai tôn giáo này đã cùng với người dân Nam Bộ tham gia kháng chiến chống giặc cứu nước”. Vấn đề vừa nêu thuộc đặc điểm thứ mấy trong số các đặc điểm tôn giáo ở Việt Nam?","options":["1","2","3","4"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Đặc điểm thứ ba là tín đồ các tôn giáo Việt Nam phần lớn là nhân dân lao động, có lòng yêu nước, tinh thần dân tộc. Việc tham gia kháng chiến minh họa nội dung này. Chi tiết tôn giáo nội sinh thuộc phần đặc điểm thứ nhất nhưng không phải trọng tâm tình huống.","trick":"Kháng chiến, cứu nước → lòng yêu nước → đặc điểm 3. Đừng chỉ bám từ “nội sinh”.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 223–224 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 57","image":"assets/mln131/q57.png","sourceExam":"mln131_01","sourceId":57,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 57","keywords":["Đạo Cao Đài, Phật giáo Hòa Hảo","tôn giáo nội sinh","tham gia kháng chiến"]},{"id":21,"stem":"Đâu không phải là một trong những điểm tương đối ổn định của giai cấp công nhân ngày nay so với giai cấp công nhân thế kỷ XIX?","options":["Giai cấp công nhân vẫn là lực lượng sản xuất hàng đầu của xã hội hiện đại","Giai cấp công nhân vẫn bị chủ nghĩa tư bản và giai cấp tư sản bóc lột giá trị thặng dư","Giai cấp công nhân vẫn có lợi ích cơ bản xung đột với lợi ích cơ bản của giai cấp tư sản","Giai cấp công nhân vẫn làm việc với cường độ cao, trình độ lao động ngày càng yếu kém"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"A, B, C tương ứng các điểm tương đối ổn định sách nêu. D không đúng: phần biến đổi của công nhân hiện đại nhấn mạnh xu hướng trí tuệ hóa, đào tạo và nâng cao tri thức, kỹ năng.","trick":"Chú ý KHÔNG PHẢI; “trình độ ngày càng yếu kém” trái với xu hướng trí tuệ hóa.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 65–68 (số in trên sách) · Bản trong Source · Nhóm ảnh 01 · Câu gốc 60","image":"assets/mln131/q60.png","sourceExam":"mln131_01","sourceId":60,"sourceKey":"mln131_unified_01_21_v1","sourceLegacyKey":"mln131_unified_01_21_v0","sourceLabel":"Nhóm ảnh 01 · Câu gốc 60","keywords":["không phải","tương đối ổn định","giai cấp công nhân"]},{"id":22,"stem":"Đặc trưng cơ bản đầu tiên của chủ nghĩa xã hội là gì?","options":["Chủ nghĩa xã hội có nhà nước kiểu mới mang bản chất giai cấp công nhân, đại biểu cho lợi ích, quyền lực và ý chí của nhân dân lao động","Chủ nghĩa xã hội giải phóng giai cấp, giải phóng dân tộc, giải phóng xã hội, giải phóng con người, tạo điều kiện để con người phát triển toàn diện","Chủ nghĩa xã hội là xã hội do nhân dân lao động làm chủ","Chủ nghĩa xã hội có nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và chế độ công hữu về tư liệu sản xuất chủ yếu"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Trong mục Những đặc trưng bản chất của chủ nghĩa xã hội, nội dung được liệt kê đầu tiên là giải phóng giai cấp, dân tộc, xã hội và con người, tạo điều kiện cho con người phát triển toàn diện. Các phương án khác nói đến những đặc trưng khác, không phải đặc trưng đầu tiên.","trick":"Hỏi đặc trưng đầu tiên của CNXH nói chung → giải phóng và phát triển con người.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 93 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 4","image":"assets/mln131/bo02/q04.png","sourceExam":"mln131_02","sourceId":4,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 4","keywords":["Đặc trưng cơ bản đầu tiên"]},{"id":23,"stem":"Đâu là một trong tám đặc trưng cơ bản của chủ nghĩa xã hội ở Việt Nam được đề cập trong Văn kiện Đại hội đại biểu toàn quốc lần thứ XI của Đảng Cộng sản Việt Nam?","options":["Dân giàu, nước mạnh, dân chủ, văn minh","Dân giàu, nước mạnh, con người có cuộc sống ấm no","Do nhân dân làm chủ","Nhà nước pháp quyền xã hội chủ nghĩa, nhà nước của nhân dân lao động"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Danh sách tám đặc trưng trong Cương lĩnh bổ sung, phát triển năm 2011 nêu đúng nguyên văn ý Do nhân dân làm chủ. A bỏ mất công bằng; B ghép các ý; D không diễn đạt đầy đủ đặc trưng về Nhà nước trong danh sách.","trick":"Chọn đúng cụm của Cương lĩnh 2011: Do nhân dân làm chủ.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 113–114 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 5","image":"assets/mln131/bo02/q05.png","sourceExam":"mln131_02","sourceId":5,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 5","keywords":["tám đặc trưng cơ bản","lần thứ XI"]},{"id":24,"stem":"Chủ nghĩa Mác Lênin đã chia lịch sử vận động và phát triển của xã hội thành mấy hình thái kinh tế xã hội?","options":["2","3","4","5"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Sách liệt kê năm hình thái kinh tế - xã hội: cộng sản nguyên thủy, chiếm hữu nô lệ, phong kiến, tư bản chủ nghĩa và cộng sản chủ nghĩa.","trick":"Đếm đủ 5 hình thái; CNXH thuộc giai đoạn thấp của hình thái cộng sản chủ nghĩa, không tính thành hình thái thứ sáu.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 104 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 6","image":"assets/mln131/bo02/q06.png","sourceExam":"mln131_02","sourceId":6,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 6","keywords":["chia lịch sử","mấy hình thái kinh tế xã hội"]},{"id":25,"stem":"Vấn đề: “Dân giàu, nước mạnh, dân chủ, công bằng, văn minh” là đặc trưng thứ mấy trong 08 đặc trưng cơ bản của chủ nghĩa xã hội ở Việt Nam? (Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội bổ sung, phát triển năm 2011)","options":["1","3","6","8"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Dân giàu, nước mạnh, dân chủ, công bằng, văn minh đứng đầu danh sách tám đặc trưng trong Cương lĩnh 2011 mà giáo trình trình bày.","trick":"Đặc trưng đầu tiên của mô hình Việt Nam 2011 → dân giàu, nước mạnh, dân chủ, công bằng, văn minh. Phân biệt câu 4 hỏi CNXH nói chung.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 114 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 7","image":"assets/mln131/bo02/q07.png","sourceExam":"mln131_02","sourceId":7,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 7","keywords":["Dân giàu, nước mạnh, dân chủ, công bằng, văn minh","thứ mấy"]},{"id":26,"stem":"Những lực lượng nào đóng vai trò quan trọng trong việc đẩy mạnh nghiên cứu sáng tạo và ứng dụng các thành tựu khoa học - công nghệ hiện đại?","options":["Đội ngũ trí thức, đội ngũ doanh nhân","Giai cấp công nhân, đội ngũ trí thức","Đội ngũ trí thức, giai cấp nông dân","Đội ngũ doanh nhân, tầng lớp lao động trong xã hội"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Trong giải pháp hoàn thiện thể chế và đẩy mạnh khoa học - công nghệ, giáo trình nêu vai trò rất quan trọng của đội ngũ trí thức và đội ngũ doanh nhân để thực hiện nghiên cứu sáng tạo, ứng dụng thành tựu hiện đại.","trick":"Cụm nghiên cứu sáng tạo + ứng dụng trong đoạn giải pháp này → trí thức và doanh nhân.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 192 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 10","image":"assets/mln131/bo02/q10.png","sourceExam":"mln131_02","sourceId":10,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 10","keywords":["nghiên cứu sáng tạo","khoa học - công nghệ"]},{"id":27,"stem":"Yếu tố nào quyết định sự liên minh giữa giai cấp công nhân, giai cấp nông dân và tầng lớp trí thức?","options":["Do giai cấp công nhân mong muốn","Do có cùng một kẻ thù là giai cấp tư sản","Do mục tiêu về chính trị của giai cấp công nhân","Do có những lợi ích cơ bản thống nhất với nhau"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Cơ sở của liên minh là các nhu cầu, lợi ích phù hợp và thống nhất giữa những giai cấp, tầng lớp tham gia. Sách cũng nêu liên minh xuất phát từ chính nhu cầu và lợi ích kinh tế của họ, không chỉ từ mong muốn chủ quan.","trick":"Liên minh bền vững dựa trên lợi ích cơ bản thống nhất.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 173–176 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 14","image":"assets/mln131/bo02/q14.png","sourceExam":"mln131_02","sourceId":14,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 14","keywords":["Yếu tố nào quyết định","liên minh"]},{"id":28,"stem":"Trong hệ thống chính sách xã hội của nước ta, các chính sách liên quan đến cơ cấu xã hội nào phải được đặt lên vị trí hàng đầu?","options":["Cơ cấu xã hội - giai cấp","Cơ cấu xã hội - kinh tế","Cơ cấu xã hội - nghề nghiệp","Cơ cấu xã hội - dân tộc"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Giáo trình nêu rõ trong hệ thống chính sách xã hội, chính sách liên quan đến cơ cấu xã hội - giai cấp cần được đặt lên vị trí hàng đầu.","trick":"Chính sách xã hội ưu tiên cơ cấu xã hội - giai cấp.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 188–189 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 15","image":"assets/mln131/bo02/q15.png","sourceExam":"mln131_02","sourceId":15,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 15","keywords":["cơ cấu xã hội","vị trí hàng đầu"]},{"id":29,"stem":"Có bao nhiêu phương hướng cơ bản xây dựng và phát triển gia đình Việt Nam trong thời kỳ quá độ lên chủ nghĩa xã hội?","options":["3","4","5","6"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Gia đình","detail":"Mục phương hướng liệt kê bốn nội dung: tăng cường lãnh đạo và nhận thức; phát triển kinh tế - xã hội, nâng đời sống gia đình; kế thừa truyền thống kết hợp tiến bộ nhân loại; nâng cao chất lượng phong trào gia đình văn hóa.","trick":"Nhớ bốn nhóm: lãnh đạo – kinh tế – giá trị – gia đình văn hóa.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 266–268 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 22","image":"assets/mln131/bo02/q22.png","sourceExam":"mln131_02","sourceId":22,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 22","keywords":["bao nhiêu phương hướng","gia đình Việt Nam"]},{"id":30,"stem":"Dưới góc độ chính trị, quy luật mang tính phổ biến và là động lực lớn cho sự phát triển của các xã hội có giai cấp là gì?","options":["Quy luật vừa hợp tác vừa đấu tranh giữa các giai cấp, tầng lớp trong xã hội","Quy luật liên minh các giai cấp, tầng lớp nhằm thực hiện mục tiêu chung","Quy luật đấu tranh giai cấp của các giai cấp có lợi ích đối lập nhau","Quy luật điều hòa lợi ích giữa các giai cấp, tầng lớp trong xã hội"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Trong mục Liên minh giai cấp, tầng lớp, sách giải thích: đấu tranh giai cấp đặt ra nhu cầu tìm đồng minh có lợi ích phù hợp để tập hợp lực lượng thực hiện nhu cầu, lợi ích chung; ngay sau đó gọi đây là quy luật mang tính phổ biến và động lực lớn. Theo đúng ngữ cảnh đoạn này, B diễn đạt nội dung được hỏi.","trick":"Đừng tách câu khỏi mục Liên minh: lợi ích phù hợp → tập hợp lực lượng → mục tiêu chung.","caution":"C dễ gây nhầm vì đấu tranh giai cấp xuất hiện đầu đoạn. Căn cứ chọn B là toàn bộ lập luận về nhu cầu liên minh và mục tiêu chung ở cuối trang 173, tiếp đầu trang 174.","reference":"Giáo trình CNXH khoa học (2021), trang 173–174 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 25","image":"assets/mln131/bo02/q25.png","sourceExam":"mln131_02","sourceId":25,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 25","keywords":["góc độ chính trị","quy luật","động lực lớn"]},{"id":31,"stem":"Trong các kiểu nhà nước dưới đây, nhà nước nào là nhà nước của tất cả mọi người, mọi giai cấp?","options":["Nhà nước chiếm hữu nô lệ","Nhà nước tư sản","Nhà nước xã hội chủ nghĩa","Không có kiểu nhà nước nào là của tất cả giai cấp"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Dân chủ và nhà nước XHCN","detail":"Giáo trình phân biệt bản chất giai cấp của các kiểu nhà nước. Ngay nhà nước xã hội chủ nghĩa cũng mang bản chất giai cấp công nhân, đại biểu ý chí của nhân dân lao động, không phải nhà nước phi giai cấp của tất cả mọi giai cấp.","trick":"Nhân dân lao động không đồng nghĩa mọi giai cấp, kể cả giai cấp bóc lột.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 143–144 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 30","image":"assets/mln131/bo02/q30.png","sourceExam":"mln131_02","sourceId":30,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 30","keywords":["tất cả mọi người, mọi giai cấp"]},{"id":32,"stem":"Dân chủ xã hội chủ nghĩa được xem là phôi thai từ thực tiễn đấu tranh giai cấp ở quốc gia nào?","options":["Ở Đức","Ở Pháp","Ở Liên Xô","Ở Trung Quốc"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Dân chủ và nhà nước XHCN","detail":"Sách nêu dân chủ xã hội chủ nghĩa phôi thai từ thực tiễn đấu tranh giai cấp ở Pháp và Công xã Pari 1871; đến Cách mạng Tháng Mười Nga 1917 mới chính thức được xác lập.","trick":"Phôi thai → Pháp, 1871; chính thức xác lập → Nga, 1917.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 133 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 32","image":"assets/mln131/bo02/q32.png","sourceExam":"mln131_02","sourceId":32,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 32","keywords":["Dân chủ xã hội chủ nghĩa","phôi thai","quốc gia nào"]},{"id":33,"stem":"Đáp án nào không phải là một giải pháp nhằm cải cách thể chế và phương thức hoạt động của Nhà nước xã hội chủ nghĩa Việt Nam?","options":["Kiện toàn tổ chức, đổi mới phương thức và nâng cao hiệu quả hoạt động của Quốc hội","Đẩy mạnh cải cách hành chính, giảm bớt và bãi bỏ các thủ tục hành chính gây phiền hà cho tổ chức và công dân","Đẩy mạnh xã hội hóa các ngành dịch vụ công phù hợp với cơ chế thị trường định hướng xã hội chủ nghĩa","Phát huy sức mạnh dân tộc và sức mạnh thời đại trong thời kỳ công nghiệp hóa, hiện đại hóa đất nước"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Dân chủ và nhà nước XHCN","detail":"Trong giải pháp Cải cách thể chế và phương thức hoạt động của Nhà nước, sách nêu lần lượt các nội dung tương ứng A, B và C. D không thuộc nhóm giải pháp cụ thể này.","trick":"Câu hỏi KHÔNG PHẢI trong nhóm cụ thể: Quốc hội – hành chính – dịch vụ công đều nằm trong sách.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 162–163 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 34","image":"assets/mln131/bo02/q34.png","sourceExam":"mln131_02","sourceId":34,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 34","keywords":["không phải","cải cách thể chế","phương thức hoạt động"]},{"id":34,"stem":"Thuật ngữ “dân chủ” được ra đời khi nào?","options":["Thế kỷ VI - VII","Thế kỷ VII - VI trước Công nguyên","Thế kỷ V - IV trước Công nguyên","Thế kỷ XXI"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Dân chủ và nhà nước XHCN","detail":"Dòng đầu phần Quan niệm về dân chủ xác định thuật ngữ này ra đời khoảng thế kỷ VII - VI trước Công nguyên, gắn với tư tưởng Hy Lạp cổ đại.","trick":"Dân chủ: VII–VI, nhớ đủ trước Công nguyên.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 126 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 35","image":"assets/mln131/bo02/q35.png","sourceExam":"mln131_02","sourceId":35,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 35","keywords":["Thuật ngữ","dân chủ","ra đời khi nào"]},{"id":35,"stem":"Cuộc đấu tranh của giai cấp vô sản chống lại nội dung gì của giai cấp tư sản?","options":["Chống lại sự thống trị, áp bức","Chống lại chế độ độc tài","Chống lại sự bóc lột, độc quyền","Chống lại sự thống trị, độc tôn"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn CNXH khoa học","detail":"Trong phần điều kiện kinh tế - xã hội ra đời CNXH khoa học, giáo trình dùng đúng cụm cuộc đấu tranh của giai cấp vô sản chống lại sự thống trị, áp bức của giai cấp tư sản.","trick":"Bám đúng cặp từ trong đoạn nguồn: thống trị, áp bức.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 13 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 39","image":"assets/mln131/bo02/q39.png","sourceExam":"mln131_02","sourceId":39,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 39","keywords":["giai cấp vô sản","chống lại","giai cấp tư sản"]},{"id":36,"stem":"Về mặt thực tiễn, đâu không phải là một ý nghĩa của việc nghiên cứu chủ nghĩa xã hội khoa học?","options":["Thấy rõ khoảng cách giữa lý luận chủ nghĩa xã hội khoa học và thực tiễn vận dụng nó","Sự sụp đổ của Liên Xô và Đông Âu là do đã nhận thức và hành động trên nhiều vấn đề trái với chủ nghĩa xã hội khoa học, trái với chủ nghĩa Mác - Lênin chứ không phải là do đi theo chủ nghĩa xã hội khoa học làm cho các nước này khủng hoảng","Cần có bản lĩnh vững vàng, sáng suốt và sáng tạo trong việc vận dụng chủ nghĩa xã hội khoa học vào hoàn cảnh lịch sử cụ thể của từng quốc gia, tránh giáo điều, bảo thủ, duy ý chí","Giúp chúng ta có căn cứ nhận thức khoa học để luôn cảnh giác, phân tích đúng và đấu tranh chống lại những nhận thức sai lệch về chủ nghĩa xã hội"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn CNXH khoa học","detail":"Đoạn về có căn cứ nhận thức khoa học để cảnh giác, phân tích và đấu tranh chống nhận thức sai lệch được đặt trước đề mục b) Về mặt thực tiễn, tức thuộc phần ý nghĩa lý luận. Các nội dung tương ứng A, B, C nằm trong phần thực tiễn.","trick":"Hỏi KHÔNG PHẢI về thực tiễn → kiểm tra ranh giới đề mục, D thuộc phần lý luận.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 46–49 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 40","image":"assets/mln131/bo02/q40.png","sourceExam":"mln131_02","sourceId":40,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 40","keywords":["thực tiễn","không phải","ý nghĩa"]},{"id":37,"stem":"Tư duy của Nhà triết học nào được xem là “cái hạt nhân hợp lý của phép biện chứng”?","options":["V.I. Lênin","C. Mác","G.V.Ph. Hêghen","Ph. Ăngghen"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn CNXH khoa học","detail":"Sách trình bày triết học Hêghen tuy duy tâm nhưng chứa hạt nhân hợp lý của phép biện chứng. Mác và Ăngghen kế thừa, cải tạo hạt nhân đó và loại bỏ vỏ thần bí duy tâm.","trick":"Hạt nhân phép biện chứng được kế thừa từ Hêghen; Mác và Ăngghen là những người cải tạo, phát triển.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 18–19 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 43","image":"assets/mln131/bo02/q43.png","sourceExam":"mln131_02","sourceId":43,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 43","keywords":["hạt nhân hợp lý","phép biện chứng"]},{"id":38,"stem":"Một trong ba phát kiến vĩ đại của C. Mác và Ph. Ăngghen là gì?","options":["Thành lập quốc tế cộng sản","Ủng hộ nhân dân lao động","Học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân","Nhận định và tìm ra mâu thuẫn giai cấp trong xã hội"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn CNXH khoa học","detail":"Ba phát kiến được sách nêu là chủ nghĩa duy vật lịch sử, học thuyết giá trị thặng dư và học thuyết về sứ mệnh lịch sử toàn thế giới của giai cấp công nhân. C là phát kiến thứ ba.","trick":"Ba phát kiến: duy vật lịch sử – giá trị thặng dư – sứ mệnh công nhân.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 19–20 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 44","image":"assets/mln131/bo02/q44.png","sourceExam":"mln131_02","sourceId":44,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 44","keywords":["ba phát kiến vĩ đại"]},{"id":39,"stem":"Sự thống trị của giai cấp tư sản, đặc biệt là bộ phận tư sản công nghiệp là điều kiện ban đầu cho sự phát triển của giai cấp nào?","options":["Sự phát triển giai cấp tư sản","Sự phát triển giai cấp chủ nô","Sự phát triển giai cấp nông dân","Sự phát triển giai cấp công nhân"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Sách xác định giai cấp công nhân là sản phẩm của nền đại công nghiệp, hình thành và phát triển cùng công nghiệp hiện đại; xét về chính trị - xã hội, đây còn là sản phẩm xã hội của sự phát triển tư bản chủ nghĩa. Từ nội dung đó, đáp án phù hợp là giai cấp công nhân.","trick":"Đại công nghiệp và quan hệ tư bản phát triển → giai cấp công nhân hình thành, phát triển.","caution":"Đây là lựa chọn suy ra từ nội dung về sự hình thành giai cấp công nhân ở trang 53–55, không phải câu trích nguyên văn tìm được trong sách.","reference":"Giáo trình CNXH khoa học (2021), trang 53–55 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 47","image":"assets/mln131/bo02/q47.png","sourceExam":"mln131_02","sourceId":47,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 47","keywords":["tư sản công nghiệp","điều kiện ban đầu","giai cấp nào"]},{"id":40,"stem":"Mâu thuẫn cơ bản của phương thức sản xuất tư bản chủ nghĩa là gì?","options":["Mâu thuẫn giữa lực lượng sản xuất xã hội hóa ngày càng rộng lớn với quan hệ sản xuất tư bản chủ nghĩa dựa trên chế độ tư hữu tư bản chủ nghĩa về tư liệu sản xuất","Mâu thuẫn giữa quan hệ sản xuất xã hội hóa ngày càng rộng lớn với lực lượng sản xuất tư bản chủ nghĩa dựa trên chế độ tư hữu tư bản chủ nghĩa về tư liệu sản xuất","Mâu thuẫn giữa cơ sở hạ tầng và kiến trúc thượng tầng","Mâu thuẫn giữa tồn tại xã hội và ý thức xã hội"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Giáo trình nêu trực tiếp mâu thuẫn giữa lực lượng sản xuất xã hội hóa ngày càng rộng lớn và quan hệ sản xuất dựa trên tư hữu tư bản chủ nghĩa về tư liệu sản xuất. B đảo vai trò hai vế; C và D không phải cách xác định mâu thuẫn cơ bản cụ thể này.","trick":"Lực lượng sản xuất: xã hội hóa; quan hệ sản xuất: tư hữu tư bản.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 54–55 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 48","image":"assets/mln131/bo02/q48.png","sourceExam":"mln131_02","sourceId":48,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 48","keywords":["Mâu thuẫn cơ bản","phương thức sản xuất tư bản chủ nghĩa"]},{"id":41,"stem":"Các chủ trương, chính sách phát triển kinh tế - xã hội miền núi, vùng đồng bào các dân tộc thiểu số ở nước ta nhằm mục đích gì?","options":["Phát huy tiềm năng phát triển, rút ngắn khoảng cách chênh lệch giữa các vùng, các dân tộc","Bù đắp cho đồng bào ở các nơi này để động viên họ cố gắng giữ gìn bờ cõi quốc gia","Giảm thiểu sự lợi dụng điều kiện sống cực khổ của các nơi này để kích động thực hiện mưu đồ chia rẽ","Tận dụng mọi nguồn lực để tăng trưởng kinh tế khi ở các vùng đồng bằng đã cạn kiệt"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Trong nội dung kinh tế của chính sách dân tộc, sách nêu mục tiêu phát huy tiềm năng phát triển và từng bước khắc phục khoảng cách chênh lệch giữa các vùng, giữa các dân tộc.","trick":"Chính sách phát triển vùng dân tộc → phát huy tiềm năng + thu hẹp chênh lệch.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 212 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 52","image":"assets/mln131/bo02/q52.png","sourceExam":"mln131_02","sourceId":52,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 52","keywords":["miền núi","dân tộc thiểu số","mục đích"]},{"id":42,"stem":"Nguyên tắc nào là cơ sở vững chắc để thực hiện đoàn kết các tầng lớp nhân dân lao động thuộc các dân tộc trong cuộc đấu tranh chống chủ nghĩa đế quốc?","options":["Liên hiệp công nhân các dân tộc","Các dân tộc hoàn toàn bình đẳng","Tăng cường mở rộng giao lưu quốc tế","Các dân tộc được quyền tự quyết"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Sách nêu đoàn kết, liên hiệp công nhân các dân tộc là cơ sở vững chắc để đoàn kết các tầng lớp nhân dân lao động thuộc các dân tộc trong đấu tranh chống chủ nghĩa đế quốc vì độc lập dân tộc và tiến bộ xã hội.","trick":"Hỏi cơ sở đoàn kết các tầng lớp lao động chống đế quốc → liên hiệp công nhân.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 205 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 53","image":"assets/mln131/bo02/q53.png","sourceExam":"mln131_02","sourceId":53,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 53","keywords":["Nguyên tắc","đoàn kết","chống chủ nghĩa đế quốc"]},{"id":43,"stem":"Trong một quốc gia đa tộc người thì vấn đề gì cần giải quyết được coi là có ý nghĩa cơ bản nhất để thực hiện quyền bình đẳng giữa các dân tộc?","options":["Ban hành hệ thống hiến pháp và pháp luật về quyền bình đẳng giữa các dân tộc","Nâng cao trình độ dân trí, văn hóa cho đồng bào","Chống tư tưởng phân biệt chủng tộc, kì thị và chia rẽ dân tộc","Xóa bỏ dần sự chênh lệch về mọi mặt giữa các dân tộc do lịch sử để lại"],"correct":[3],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc và tôn giáo","detail":"Sách nhấn mạnh bình đẳng dân tộc phải được thực hiện trên thực tế, không chỉ trên cơ sở pháp lý; phát triển kinh tế - xã hội là nền tảng thực hiện bình đẳng và từng bước khắc phục chênh lệch trình độ phát triển. Trong các phương án, D diễn đạt phù hợp nhất yêu cầu bình đẳng thực tế.","trick":"Pháp luật là cơ sở; bình đẳng thực tế đòi hỏi khắc phục chênh lệch phát triển.","caution":"Chọn D theo lập luận của giáo trình về bình đẳng thực tế và khắc phục chênh lệch; cụm có ý nghĩa cơ bản nhất trong đề là cách diễn đạt khái quát.","reference":"Giáo trình CNXH khoa học (2021), trang 204; 212–213 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 56","image":"assets/mln131/bo02/q56.png","sourceExam":"mln131_02","sourceId":56,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 56","keywords":["quốc gia đa tộc người","cơ bản nhất","bình đẳng"]},{"id":44,"stem":"Theo chủ nghĩa Mác - Lênin, chất lượng của giai cấp công nhân được thể hiện thông qua yếu tố nào?","options":["Sự chuyên nghiệp trong tác phong, kỷ luật lao động","Trình độ trưởng thành về ý thức chính trị của một giai cấp cách mạng","Năng lực tập hợp, vận động và thống trị nhân dân lao động thông qua đội tiên phong của mình - Đảng Cộng sản","Năng lực tổ chức khởi nghĩa giành chính quyền"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Sách xác định trực tiếp chất lượng giai cấp công nhân thể hiện ở trình độ trưởng thành về ý thức chính trị của một giai cấp cách mạng. Sách còn nêu năng lực làm chủ khoa học, kỹ thuật, công nghệ; C không phải nội dung đó.","trick":"Cặp từ đúng trong sách: chất lượng → trưởng thành về ý thức chính trị.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 63 (số in trên sách) · Bản trong Source · Nhóm ảnh 02 · Câu gốc 60","image":"assets/mln131/bo02/q60.png","sourceExam":"mln131_02","sourceId":60,"sourceKey":"mln131_unified_02_bank_v1","sourceLegacyKey":"mln131_unified_02_bank_v0","sourceLabel":"Nhóm ảnh 02 · Câu gốc 60","keywords":["chất lượng","giai cấp công nhân"]},{"id":45,"stem":"Nhân tố nào sau đây có vai trò quyết định đến sự tồn tại và phát triển của xã hội?","options":["Con người","Gia đình","Tư duy","Khoa học kỹ thuật"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Gia đình","detail":"Trong phần Khái niệm gia đình, sách xác định gia đình là một cộng đồng người đặc biệt có vai trò quyết định đến sự tồn tại và phát triển của xã hội. Phần vị trí gia đình tiếp tục giải thích vai trò tái tạo con người của gia đình. Theo cách diễn đạt của giáo trình ở câu này, chọn Gia đình.","trick":"Cụm vai trò quyết định đến sự tồn tại và phát triển của xã hội nằm trong định nghĩa gia đình.","caution":"Câu hỏi tách khỏi ngữ cảnh dễ khiến nhầm sang Con người; đối chiếu đúng đoạn định nghĩa gia đình trong nguồn.","reference":"Giáo trình CNXH khoa học (2021), trang 239–242 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 60","image":"assets/mln131/bo03/q60.png","sourceExam":"mln131_03","sourceId":60,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 60","keywords":["vai trò quyết định","tồn tại và phát triển","xã hội"]},{"id":46,"stem":"Khác biệt về sự ra đời của hình thái kinh tế - xã hội cộng sản chủ nghĩa với sự ra đời của các hình thái kinh tế - xã hội trước đây là gì?","options":["Phải được thực hiện thông qua cuộc cách mạng vô sản","Phải được thực hiện thông qua cuộc cách mạng tư sản","Phải được thực hiện thông qua một sự cải biến sâu sắc về trình độ phát triển của công nghiệp và người lao động","Phải có sự hội tụ đầy đủ các yếu tố về kinh tế và chính trị"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Sách nêu hình thái kinh tế - xã hội cộng sản chủ nghĩa không tự nhiên ra đời mà được hình thành thông qua cách mạng vô sản dưới sự lãnh đạo của Đảng Cộng sản. Đây là điểm khác biệt mà câu hỏi yêu cầu.","trick":"Sự ra đời của hình thái cộng sản chủ nghĩa → cách mạng vô sản.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 92 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 4","image":"assets/mln131/bo03/q04.png","sourceExam":"mln131_03","sourceId":4,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 4","keywords":["Khác biệt","sự ra đời","cộng sản chủ nghĩa"]},{"id":47,"stem":"Đối tượng nghiên cứu của chủ nghĩa xã hội khoa học là gì?","options":["Là những quy luật, tính quy luật chính trị - xã hội của quá trình phát sinh, hình thành và phát triển của hình thái kinh tế - xã hội cộng sản chủ nghĩa","Là những quy luật, tính quy luật chính trị - xã hội của quá trình phát sinh, hình thành và phát triển của hình thái kinh tế - xã hội xã hội chủ nghĩa","Là những quy luật, tính quy luật chính trị - xã hội của quá trình phát sinh, hình thành và phát triển của hình thái kinh tế - xã hội tư bản chủ nghĩa","Là những quy luật, tính quy luật chính trị - xã hội của quá trình phát sinh, hình thành và phát triển của hình thái kinh tế - xã hội tư bản chủ nghĩa và cộng sản chủ nghĩa"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn chủ nghĩa xã hội khoa học","detail":"Đoạn khái quát đối tượng nghiên cứu nêu các quy luật, tính quy luật chính trị - xã hội của quá trình phát sinh, hình thành và phát triển hình thái kinh tế - xã hội cộng sản chủ nghĩa, mà giai đoạn thấp là chủ nghĩa xã hội. Trong bốn phương án, A phù hợp.","trick":"Đối tượng → hình thái kinh tế - xã hội cộng sản chủ nghĩa.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 42 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 11","image":"assets/mln131/bo03/q11.png","sourceExam":"mln131_03","sourceId":11,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 11","keywords":["Đối tượng nghiên cứu","chủ nghĩa xã hội khoa học"]},{"id":48,"stem":"Sau khi chế độ xã hội chủ nghĩa Liên Xô và Đông Âu sụp đổ, chủ nghĩa xã hội khoa học được bổ sung và phát triển như thế nào?","options":["Được giới tri thức thế giới nghiên cứu như một học thuyết đã lỗi thời","Được các nước xã hội chủ nghĩa bổ sung và phát triển trong tình hình mới, phù hợp với bối cảnh từng nước","Các nước tư bản chủ nghĩa nghiên cứu chủ nghĩa xã hội khoa học như một học thuyết nhằm khắc phục các khuyết tật của thời đại mới","Được dung hòa cùng với các học thuyết tư sản khác"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Nhập môn chủ nghĩa xã hội khoa học","detail":"Sau sự sụp đổ ở Liên Xô và Đông Âu, ở những nước tiếp tục định hướng xã hội chủ nghĩa, các Đảng Cộng sản từng bước bổ sung, phát triển lý luận Mác - Lênin và chủ nghĩa xã hội khoa học phù hợp bối cảnh mới.","trick":"Tiếp tục bổ sung và phát triển phù hợp bối cảnh mới.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 34 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 13","image":"assets/mln131/bo03/q13.png","sourceExam":"mln131_03","sourceId":13,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 13","keywords":["Liên Xô và Đông Âu sụp đổ","bổ sung và phát triển"]},{"id":49,"stem":"Có bao nhiêu phương hướng được đề ra tại Văn kiện Đại hội đại biểu toàn quốc lần thứ XI trong thời kỳ quá độ lên chủ nghĩa xã hội?","options":["5","6","8","9"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Sách xác định Đại hội XI đề ra tám phương hướng, rồi lần lượt liệt kê từ Một là đến Tám là.","trick":"Đại hội XI: 8 đặc trưng, 8 phương hướng; đọc đúng nội dung đang hỏi.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 116–117 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 14","image":"assets/mln131/bo03/q14.png","sourceExam":"mln131_03","sourceId":14,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 14","keywords":["bao nhiêu phương hướng","lần thứ XI"]},{"id":50,"stem":"Trong gia đình, quan hệ thứ ba tham gia ngay từ đầu vào quá trình phát triển lịch sử, đó là quan hệ nào?","options":["Quan hệ giữa chồng và vợ, quan hệ giữa cha mẹ và con cái","Quan hệ giữa ông bà với con cái, quan hệ giữa vợ và chồng","Quan hệ giữa tổ tiên với ông bà, cha mẹ","Quan hệ giữa con cái và cha mẹ"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Gia đình","detail":"Đoạn trích của C. Mác và Ph. Ăngghen giải thích quan hệ thứ ba là quan hệ giữa chồng và vợ, cha mẹ và con cái, tức gia đình. A diễn đạt đầy đủ cả hai mối quan hệ cơ bản.","trick":"Quan hệ thứ ba → vợ chồng + cha mẹ, con cái.","caution":"Cùng khai thác đoạn giáo trình với câu 39 của nhóm ảnh đầu, nhưng phương án hỏi về hai quan hệ cấu thành thay vì tên gọi Gia đình.","reference":"Giáo trình CNXH khoa học (2021), trang 240 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 17","image":"assets/mln131/bo03/q17.png","sourceExam":"mln131_03","sourceId":17,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 17","keywords":["gia đình","quan hệ thứ ba"]},{"id":51,"stem":"Trong thời kì quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay, giai cấp công nhân có vị trí, vai trò như thế nào trong khối liên minh giai cấp?","options":["Là lực lượng nòng cốt, tiên phong trong liên minh giai cấp","Là lực lượng hỗ trợ duy trì liên minh","Là lực lượng duy trì khối đại đoàn kết của giai cấp công nhân, nông dân với tư sản và trí thức","Là lực lượng củng cố khối đại đoàn kết dân tộc"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Sách xác định giai cấp công nhân giữ vị trí tiên phong và là lực lượng nòng cốt trong liên minh giai cấp công nhân với giai cấp nông dân và đội ngũ trí thức.","trick":"Vị trí của công nhân trong liên minh → nòng cốt, tiên phong.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 178–179 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 24","image":"assets/mln131/bo03/q24.png","sourceExam":"mln131_03","sourceId":24,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 24","keywords":["giai cấp công nhân","vị trí, vai trò","khối liên minh"]},{"id":52,"stem":"Ở Việt Nam hiện nay, tổ chức nào đại diện cho quyền lợi, lợi ích hợp pháp và là nơi để giai cấp công nhân chủ động, tích cực tham gia xây dựng, chỉnh đốn Đảng, bảo vệ chế độ xã hội chủ nghĩa, bảo vệ nhân dân?","options":["Hệ thống tổ chức Công đoàn","Quốc hội","Mặt trận Tổ quốc Việt Nam","Hội đồng nhân dân các cấp"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Sách nêu công nhân thông qua hệ thống tổ chức công đoàn chủ động tham gia xây dựng, chỉnh đốn Đảng, bảo vệ Đảng và chế độ để bảo vệ nhân dân. Phần giải pháp cũng nêu vai trò đại diện, bảo vệ quyền và lợi ích hợp pháp, chính đáng của công nhân của công đoàn.","trick":"Đại diện, bảo vệ quyền lợi công nhân → Công đoàn.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 79, 82 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 29","image":"assets/mln131/bo03/q29.png","sourceExam":"mln131_03","sourceId":29,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 29","keywords":["đại diện cho quyền lợi","xây dựng, chỉnh đốn Đảng"]},{"id":53,"stem":"Nhiệm vụ cấp bách, lâu dài của quá trình xây dựng Nhà nước pháp quyền xã hội chủ nghĩa ở nước ta là gì?","options":["Phòng chống tham nhũng, lãng phí và thực hành tiết kiệm","Miễn nhiệm những người không hoàn thành nhiệm vụ","Nâng cao chất lượng đội ngũ cán bộ, công chức","Có chính sách đãi ngộ, động viên, khuyến khích cán bộ, công chức"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Dân chủ và nhà nước","detail":"Mục Bốn là về phòng, chống tham nhũng, lãng phí, thực hành tiết kiệm xác định rõ đây là nhiệm vụ cấp bách, lâu dài. Các lựa chọn còn lại thuộc nội dung xây dựng đội ngũ cán bộ, công chức.","trick":"Cấp bách, lâu dài → chống tham nhũng, lãng phí; thực hành tiết kiệm.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 163 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 30","image":"assets/mln131/bo03/q30.png","sourceExam":"mln131_03","sourceId":30,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 30","keywords":["Nhiệm vụ cấp bách, lâu dài","Nhà nước pháp quyền"]},{"id":54,"stem":"Cơ sở văn hóa để xây dựng gia đình trong chủ nghĩa xã hội là gì?","options":["Thiết lập chính quyền nhà nước của giai cấp công nhân và nhân dân lao động, nhà nước xã hội chủ nghĩa","Thiết lập chế độ công hữu về tư liệu sản xuất","Giá trị văn hóa được xây dựng trên nền tảng hệ tư tưởng chính trị của giai cấp công nhân","Xây dựng nền văn hóa tiên tiến mang đậm bản sắc dân tộc"],"correct":[2],"multiple":false,"gradable":true,"why":[],"topic":"Gia đình","detail":"Trong mục Cơ sở văn hóa, sách nêu những giá trị văn hóa được xây dựng trên nền tảng hệ tư tưởng chính trị của giai cấp công nhân từng bước giữ vai trò chi phối nền tảng văn hóa, tinh thần xã hội. A là cơ sở chính trị; B là cơ sở kinh tế.","trick":"Hỏi cơ sở văn hóa gia đình → giá trị văn hóa trên nền tảng hệ tư tưởng giai cấp công nhân.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 253 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 35","image":"assets/mln131/bo03/q35.png","sourceExam":"mln131_03","sourceId":35,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 35","keywords":["Cơ sở văn hóa","xây dựng gia đình"]},{"id":55,"stem":"Nội dung văn hóa - xã hội của liên minh giai cấp, tầng lớp là gì?","options":["Xây dựng nền văn hóa và con người Việt Nam phát triển toàn diện","Xây dựng nền văn hóa và nhà nước của dân, do dân, vì dân","Xây dựng nền văn hóa và xây dựng Đảng trong sạch, vững mạnh","Xây dựng nền văn hóa và tăng cường bản chất giai cấp công nhân"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Phần Nội dung văn hóa - xã hội của liên minh nêu xây dựng nền văn hóa và con người Việt Nam phát triển toàn diện, hướng đến chân - thiện - mỹ, cùng với phát triển nguồn nhân lực và các chính sách xã hội.","trick":"Văn hóa - xã hội của liên minh → văn hóa và con người phát triển toàn diện.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 186–187 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 36","image":"assets/mln131/bo03/q36.png","sourceExam":"mln131_03","sourceId":36,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 36","keywords":["Nội dung văn hóa - xã hội","liên minh"]},{"id":56,"stem":"Các dân tộc đều có quyền và nghĩa vụ ngang nhau trên tất cả các lĩnh vực đời sống xã hội, không phân biệt dân tộc lớn hay nhỏ, trình độ phát triển cao hay thấp là quyền gì trong Cương lĩnh dân tộc của V.I.Lênin?","options":["Quyền dân tộc tự quyết","Quyền hoàn toàn bình đẳng giữa các dân tộc","Quyền sống, quyền tự do và quyền hạnh phúc của các dân tộc","Quyền công bằng xã hội"],"correct":[1],"multiple":false,"gradable":true,"why":[],"topic":"Dân tộc","detail":"Đây là nội dung của nguyên tắc Các dân tộc hoàn toàn bình đẳng. Quyền tự quyết là tự định đoạt vận mệnh, lựa chọn chế độ và con đường phát triển, khác với quyền và nghĩa vụ ngang nhau.","trick":"Quyền và nghĩa vụ ngang nhau, không phân biệt → bình đẳng.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 204 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 38","image":"assets/mln131/bo03/q38.png","sourceExam":"mln131_03","sourceId":38,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 38","keywords":["quyền và nghĩa vụ ngang nhau","không phân biệt"]},{"id":57,"stem":"Trong thời đại hiện nay, ở các nước tư bản chủ nghĩa, mục tiêu đấu tranh trực tiếp để thực hiện sứ mệnh lịch sử của giai cấp công nhân về chính trị - xã hội là gì?","options":["Chống bất công, bất bình đẳng xã hội","Xóa bỏ chế độ tư hữu về tư liệu sản xuất","Giành chính quyền về tay giai cấp công nhân","Xác lập quyền lãnh đạo xã hội của Đảng Cộng sản"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Giai cấp công nhân","detail":"Sách phân biệt mục tiêu trực tiếp là chống bất công và bất bình đẳng xã hội; mục tiêu lâu dài là giành chính quyền về tay giai cấp công nhân và nhân dân lao động.","trick":"Tư bản hiện nay: trực tiếp chống bất công; lâu dài giành chính quyền.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 70 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 40","image":"assets/mln131/bo03/q40.png","sourceExam":"mln131_03","sourceId":40,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 40","keywords":["nước tư bản chủ nghĩa","mục tiêu đấu tranh trực tiếp","chính trị - xã hội"]},{"id":58,"stem":"Mức độ tác động của gia đình đối với xã hội phụ thuộc vào những yếu tố nào?","options":["Vào bản chất của từng chế độ xã hội","Vào đường lối, chủ trương của giai cấp cầm quyền","Vào bản thân mô hình, kết cấu, đặc điểm của mỗi hình thức gia đình trong lịch sử","Vào ý chí, nguyện vọng của các thành viên trong gia đình"],"correct":[0,1,2],"multiple":true,"gradable":true,"why":[],"topic":"Gia đình","detail":"Sách nêu liên tiếp ba yếu tố: bản chất chế độ xã hội; đường lối, chính sách của giai cấp cầm quyền; mô hình, kết cấu và đặc điểm của mỗi hình thức gia đình trong lịch sử. Do đó A, B, C đều được nguồn xác nhận.","trick":"Ba yếu tố: chế độ xã hội – chính sách cầm quyền – mô hình gia đình.","caution":"Ảnh có nhiều phương án đúng. Bản ôn ghi rõ Chọn nhiều đáp án và chấm theo A, B, C; không ép chọn một phương án.","reference":"Giáo trình CNXH khoa học (2021), trang 242 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 43","image":"assets/mln131/bo03/q43.png","sourceExam":"mln131_03","sourceId":43,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 43","keywords":["Mức độ tác động","gia đình","phụ thuộc"]},{"id":59,"stem":"Liên Xô, Đông Âu và các nước xã hội chủ nghĩa hiện nay, đã và đang quá độ lên chủ nghĩa xã hội bằng hình thức nào?","options":["Quá độ gián tiếp","Quá độ trực tiếp","Quá độ bộ phận","Quá độ toàn diện"],"correct":[0],"multiple":false,"gradable":true,"why":[],"topic":"Chủ nghĩa xã hội và thời kỳ quá độ","detail":"Sách nêu Liên Xô, Đông Âu trước đây và Trung Quốc, Việt Nam cùng một số nước xã hội chủ nghĩa hiện nay đều trải qua thời kỳ quá độ gián tiếp với những trình độ phát triển khác nhau. Trực tiếp áp dụng về lý luận cho nước đã trải qua chủ nghĩa tư bản phát triển.","trick":"Liên Xô, Đông Âu, Việt Nam theo giáo trình → quá độ gián tiếp.","caution":"","reference":"Giáo trình CNXH khoa học (2021), trang 105 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 44","image":"assets/mln131/bo03/q44.png","sourceExam":"mln131_03","sourceId":44,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 44","keywords":["Liên Xô, Đông Âu","hình thức nào"]},{"id":60,"stem":"Cơ cấu xã hội - giai cấp của nước ta trước thời kì đổi mới bao gồm các giai cấp, tầng lớp nào?","options":["Giai cấp công nhân","Giai cấp nông dân","Đội ngũ trí thức","Đội ngũ đảng viên"],"correct":[0,1,2],"multiple":true,"gradable":true,"why":[],"topic":"Liên minh và cơ cấu xã hội","detail":"Sách mô tả cơ cấu xã hội - giai cấp đơn giản của thời kỳ trước đổi mới gồm giai cấp công nhân, giai cấp nông dân và đội ngũ trí thức. Đảng viên là tư cách tham gia tổ chức chính trị, không phải một giai cấp hay tầng lớp riêng trong danh sách này.","trick":"Trước đổi mới: công nhân – nông dân – trí thức.","caution":"Ảnh có ba phương án đúng. Bản ôn ghi rõ Chọn nhiều đáp án và chấm theo A, B, C.","reference":"Giáo trình CNXH khoa học (2021), trang 178 (số in trên sách) · Bản trong Source · Nhóm ảnh 03 · Câu gốc 45","image":"assets/mln131/bo03/q45.png","sourceExam":"mln131_03","sourceId":45,"sourceKey":"mln131_unified_03_bank_v1","sourceLegacyKey":"mln131_unified_03_bank_v0","sourceLabel":"Nhóm ảnh 03 · Câu gốc 45","keywords":["trước thời kì đổi mới","giai cấp, tầng lớp"]}]}});